package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoVersionShelfReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun shelf()=unsafe.allocateInstance(VideoProjectVersionShelf::class.java)as VideoProjectVersionShelf
 private fun owner(a:HonorableVideoEditorActivity)=shelf().also{set(a,"versionShelf",it)}
 private fun draft()=VideoDraft(5000,listOf(VideoSegment(500,4500,speed=.5f,volume=.6f,title="Saved",captions=listOf(VideoCaption(500,1500,"Saved cue")),captionSourceUri="content://synthetic/saved-subtitles")),0,750,750,4250,soundtrack=VideoSoundtrack("content://synthetic/saved-music",10000,.6f,false,1000,8000))
 private fun apply(a:HonorableVideoEditorActivity,shelf:VideoProjectVersionShelf,r:VideoCaptionReviewState,p:VideoEditProject,saved:VideoDraft=draft())=call(a,"applyVersionReview",shelf,r,p,saved)as Boolean
 private fun refused(block:()->Unit){try{block();fail("accepted stale version")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException||e.cause is IllegalStateException)}}
 @Test fun canonicalVersionAppliesOnceAndPreviewFailureDoesNotRejectModel(){val a=activity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val r=capture(a);val shelf=owner(a);val saved=draft();assertFalse("metadata fixture has no preview widgets",apply(a,shelf,r,p,saved));assertEquals(saved.segments,p.segments);assertEquals(saved.soundtrack,p.soundtrack);assertEquals(750L,get(a,"pendingSeekMs"));assertNull(get(a,"versionShelf"));assertTrue(p.captionSourceUris().contains("content://synthetic/subtitles"));assertTrue(p.captionSourceUris().contains("content://synthetic/saved-subtitles"));assertTrue(p.undo());assertEquals(old,p.segments);assertSame(music,p.soundtrack);assertFalse(p.canUndo);refused{apply(a,shelf,r,p)};assertEquals(old,p.segments);assertTrue(p.canRedo)}
 @Test fun importedOriginalsMergeAndRemainAvailableAcrossTimelineUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val current=linkedMapOf("kept" to VideoSource("kept","content://synthetic/kept",7000));set(a,"importedSources",current);val primary=get(a,"source");val old=p.segments;val added=VideoSource("added","content://synthetic/added",3000);val saved=VideoDraft(5000,listOf(VideoSegment(0,3000,sourceId="added",title="Imported")),0,1000,0,3000,listOf(added));val shelf=owner(a);assertFalse(apply(a,shelf,capture(a),p,saved));assertEquals(saved.segments,p.segments);assertEquals(added,current["added"]);assertEquals(2,current.size);assertSame(primary,get(a,"source"));assertTrue(p.undo());assertEquals(old,p.segments);assertEquals(added,current["added"]);assertEquals(7000L,current["kept"]!!.durationMs)}
 @Test fun staleFullSnapshotRefusesBeforeProjectOrCatalogChanges(){for(flag in listOf("pause","source","duration","selection","generation","mode","bytes","blocked","checking","saving","analysis","draftbusy","importeduri","importedduration","project")){val a=activity();val p=get(a,"project")as VideoEditProject;set(a,"importedSources",linkedMapOf("extra" to VideoSource("extra","content://synthetic/extra",7000)));val r=capture(a);val shelf=owner(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"selection"->set(a,"selectedClip",1);"generation"->set(a,"captionReviewGeneration",r.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"bytes"->set(a,"recoveryBytes",byteArrayOf(1));"blocked"->set(a,"recoveryBlocked",true);"checking"->set(a,"recoveryChecking",true);"saving"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);"draftbusy"->set(a,"draftBusy",true);"importeduri"->set(a,"importedSources",linkedMapOf("extra" to VideoSource("extra","content://synthetic/replaced",7000)));"importedduration"->set(a,"importedSources",linkedMapOf("extra" to VideoSource("extra","content://synthetic/extra",7001)));else->set(a,"project",VideoEditProject(5000))};val clips=p.segments;val music=p.soundtrack;val catalog=get(a,"importedSources");refused{apply(a,shelf,r,p)};assertSame(clips,p.segments);assertSame(music,p.soundtrack);assertSame(catalog,get(a,"importedSources"));assertNull(get(a,"versionShelf"));assertFalse(p.canUndo)}}
 @Test fun foreignShelfCannotConsumeCurrentVersionOwner(){val a=activity();val p=get(a,"project")as VideoEditProject;val old=owner(a);val next=owner(a);val r=capture(a);val clips=p.segments;refused{apply(a,old,r,p)};assertSame(next,get(a,"versionShelf"));assertSame(clips,p.segments);assertFalse(p.canUndo);assertFalse(apply(a,next,r,p));assertNull(get(a,"versionShelf"));assertTrue(p.canUndo)}
 @Test fun shelfAdmissionRequiresIdentityAndAllowsOwnBusyRelease(){val a=activity();val shelf=owner(a);val r=capture(a);assertEquals(true,call(a,"canUseVersionReview",shelf,r));assertEquals(false,call(a,"canUseVersionReview",shelf(),r));set(a,"draftBusy",true);assertEquals(false,call(a,"canUseVersionReview",shelf,r));set(a,"draftBusy",false);assertEquals(true,call(a,"canUseVersionReview",shelf,r));set(a,"captionReviewGeneration",r.generation+1);assertEquals(false,call(a,"canUseVersionReview",shelf,r))}
 @Test fun sourceReconciliationConflictConsumesApprovalAndKeepsCurrentState(){val a=activity();val p=get(a,"project")as VideoEditProject;val current=linkedMapOf("kept" to VideoSource("kept","content://synthetic/kept",7000));set(a,"importedSources",current);val r=capture(a);val shelf=owner(a);val clips=p.segments;val music=p.soundtrack;val changed=VideoSource("other","content://synthetic/kept",8000);val saved=VideoDraft(5000,listOf(VideoSegment(0,1000,sourceId="other")),0,0,0,1000,listOf(changed));refused{apply(a,shelf,r,p,saved)};assertSame(clips,p.segments);assertSame(music,p.soundtrack);assertEquals(listOf("kept"),current.keys.toList());assertNull(get(a,"versionShelf"));assertFalse(p.canUndo)}
 @Test fun savedVersionKeepsExistingDraftCodecAndModelUndo(){val saved=draft();assertEquals(saved,VideoDraftCodec.decode(VideoDraftCodec.encode(saved),5000));val a=activity();val p=get(a,"project")as VideoEditProject;val shelf=owner(a);assertFalse(apply(a,shelf,capture(a),p,saved));assertEquals(saved.segments,p.segments);assertTrue(p.undo());assertTrue(p.redo());assertEquals(saved.soundtrack,p.soundtrack)}
 @Test fun blockedEntryReturnsBeforeRangeWidgetsShelfWorkerAndPermissionIo(){for(flag in listOf("pause","saving","bytes","blocked","checking","source")){val a=activity();when(flag){"pause"->set(a,"workspaceActive",false);"saving"->set(a,"saving",true);"bytes"->set(a,"recoveryBytes",byteArrayOf(1));"blocked"->set(a,"recoveryBlocked",true);"checking"->set(a,"recoveryChecking",true);else->set(a,"source",null)};call(a,"savedVideoVersions");assertNull(get(a,"versionShelf"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
